domain Real {
    function real_from_int(i: Int): Real
    function real_add(a: Real, b: Real): Real
    function real_sub(a: Real, b: Real): Real
    function real_mul(a: Real, b: Real): Real
    function real_div(a: Real, b: Real): Real
    function real_sqrt(r: Real): Real
    function real_clamp(r: Real, lo: Real, hi: Real): Real
    function real_lt(a: Real, b: Real): Bool
    function real_le(a: Real, b: Real): Bool
    function real_gt(a: Real, b: Real): Bool
    function real_ge(a: Real, b: Real): Bool
    function real_eq(a: Real, b: Real): Bool
    function real_is_nan(r: Real): Bool
    function real_is_inf(r: Real): Bool
    function real_zero(): Real
    function real_one(): Real
    function real_half(): Real
    function real_neg_one(): Real
    function real_max_f32(): Real
    function real_inf(): Real
    function real_neg_inf(): Real
    function real_const(v: Int, denom: Int): Real

    axiom zero_def {
        real_eq(real_zero(), real_from_int(0))
    }

    axiom one_def {
        real_eq(real_one(), real_from_int(1))
    }

    axiom clamp_lower {
        forall r: Real, lo: Real, hi: Real ::
            real_le(lo, hi) ==> real_le(lo, real_clamp(r, lo, hi))
    }

    axiom clamp_upper {
        forall r: Real, lo: Real, hi: Real ::
            real_le(lo, hi) ==> real_le(real_clamp(r, lo, hi), hi)
    }

    axiom clamp_in_range {
        forall r: Real, lo: Real, hi: Real ::
            (real_le(lo, hi) && real_le(lo, r) && real_le(r, hi)) ==> real_eq(real_clamp(r, lo, hi), r)
    }

    axiom sqrt_non_negative {
        forall r: Real ::
            real_ge(r, real_zero()) ==> real_ge(real_sqrt(r), real_zero())
    }

    axiom sqrt_square {
        forall r: Real ::
            real_ge(r, real_zero()) ==> real_eq(real_mul(real_sqrt(r), real_sqrt(r)), r)
    }

    axiom add_comm {
        forall a: Real, b: Real ::
            real_eq(real_add(a, b), real_add(b, a))
    }

    axiom mul_comm {
        forall a: Real, b: Real ::
            real_eq(real_mul(a, b), real_mul(b, a))
    }

    axiom add_zero {
        forall a: Real ::
            real_eq(real_add(a, real_zero()), a)
    }

    axiom mul_one {
        forall a: Real ::
            real_eq(real_mul(a, real_one()), a)
    }

    axiom mul_zero {
        forall a: Real ::
            real_eq(real_mul(a, real_zero()), real_zero())
    }

    axiom div_self {
        forall a: Real ::
            (!real_eq(a, real_zero()) && !real_is_nan(a) && !real_is_inf(a)) ==>
                real_eq(real_div(a, a), real_one())
    }

    axiom nan_propagation_add {
        forall a: Real, b: Real ::
            (real_is_nan(a) || real_is_nan(b)) ==> real_is_nan(real_add(a, b))
    }

    axiom nan_propagation_mul {
        forall a: Real, b: Real ::
            (real_is_nan(a) || real_is_nan(b)) ==> real_is_nan(real_mul(a, b))
    }

    axiom inf_not_nan {
        forall r: Real ::
            real_is_inf(r) ==> !real_is_nan(r)
    }

    axiom lt_not_eq {
        forall a: Real, b: Real ::
            real_lt(a, b) ==> !real_eq(a, b)
    }

    axiom le_or {
        forall a: Real, b: Real ::
            real_le(a, b) <==> (real_lt(a, b) || real_eq(a, b))
    }

    axiom gt_sym {
        forall a: Real, b: Real ::
            real_gt(a, b) <==> real_lt(b, a)
    }

    axiom ge_sym {
        forall a: Real, b: Real ::
            real_ge(a, b) <==> real_le(b, a)
    }
}

domain Hash {
    function stable_hash(data: Seq[Int], seed: Int): Int
    function stable_hash_single(val: Int, seed: Int): Int
    function hash_xor(a: Int, b: Int): Int
    function hash_wrapping_add(a: Int, b: Int): Int
    function hash_wrapping_mul(a: Int, b: Int): Int

    axiom hash_deterministic {
        forall d: Seq[Int], s: Int ::
            stable_hash(d, s) == stable_hash(d, s)
    }

    axiom hash_single_deterministic {
        forall v: Int, s: Int ::
            stable_hash_single(v, s) == stable_hash_single(v, s)
    }

    axiom xor_comm {
        forall a: Int, b: Int ::
            hash_xor(a, b) == hash_xor(b, a)
    }

    axiom xor_self {
        forall a: Int ::
            hash_xor(a, a) == 0
    }

    axiom xor_zero {
        forall a: Int ::
            hash_xor(a, 0) == a
    }

    axiom hash_non_negative {
        forall d: Seq[Int], s: Int ::
            stable_hash(d, s) >= 0
    }
}

domain BitOps {
    function pop_count(v: Int): Int
    function bit_and(a: Int, b: Int): Int
    function bit_or(a: Int, b: Int): Int
    function bit_not(a: Int): Int

    axiom pop_count_non_negative {
        forall v: Int ::
            pop_count(v) >= 0
    }

    axiom pop_count_zero {
        pop_count(0) == 0
    }

    axiom and_comm {
        forall a: Int, b: Int ::
            bit_and(a, b) == bit_and(b, a)
    }

    axiom or_comm {
        forall a: Int, b: Int ::
            bit_or(a, b) == bit_or(b, a)
    }

    axiom and_self {
        forall a: Int ::
            bit_and(a, a) == a
    }

    axiom or_self {
        forall a: Int ::
            bit_or(a, a) == a
    }

    axiom and_zero {
        forall a: Int ::
            bit_and(a, 0) == 0
    }

    axiom or_zero {
        forall a: Int ::
            bit_or(a, 0) == a
    }

    axiom pop_count_and_le {
        forall a: Int, b: Int ::
            pop_count(bit_and(a, b)) <= pop_count(a) && pop_count(bit_and(a, b)) <= pop_count(b)
    }
}

