    function bit_and(a: Int, b: Int): Int
    function bit_or(a: Int, b: Int): Int
    function bit_not(a: Int): Int

    axiom pop_count_non_negative {
        forall v: Int ::
            pop_count(v) >= 0
    }

    axiom pop_count_zero {
        pop_count(0) == 0
    }

    axiom and_comm {
        forall a: Int, b: Int ::
            bit_and(a, b) == bit_and(b, a)
    }

    axiom or_comm {
        forall a: Int, b: Int ::
            bit_or(a, b) == bit_or(b, a)
    }

    axiom and_self {
        forall a: Int ::
            bit_and(a, a) == a
    }

    axiom or_self {
        forall a: Int ::
            bit_or(a, a) == a
    }

    axiom and_zero {
        forall a: Int ::
            bit_and(a, 0) == 0
    }

    axiom or_zero {
        forall a: Int ::
            bit_or(a, 0) == a
    }

    axiom pop_count_and_le {
        forall a: Int, b: Int ::
            pop_count(bit_and(a, b)) <= pop_count(a) && pop_count(bit_and(a, b)) <= pop_count(b)
    }
}

domain RankerConfigDomain {
    function streaming_buffer_size(): Int
    function streaming_window_size(): Int
    function default_top_k_retrieval(): Int
    function hash_seed_multiplier_a(): Int
    function hash_seed_multiplier_b(): Int
    function learning_rate(): Real
    function diversity_weight(): Real
    function proximity_weight(): Real
    function max_raw_score(): Real
    function base_score_weight(): Real
    function overlap_weight(): Real
    function jaccard_weight(): Real

    axiom buffer_size_val {
        streaming_buffer_size() == 1024
    }

    axiom window_size_val {
        streaming_window_size() == 512
    }

    axiom top_k_val {
        default_top_k_retrieval() == 1000
    }

    axiom multiplier_a_positive {
        hash_seed_multiplier_a() > 0
    }

    axiom multiplier_b_positive {
        hash_seed_multiplier_b() > 0
    }

    axiom learning_rate_bounds {
        real_gt(learning_rate(), real_zero()) && real_lt(learning_rate(), real_one())
    }

    axiom diversity_weight_bounds {
        real_ge(diversity_weight(), real_zero()) && real_le(diversity_weight(), real_one())
    }

    axiom proximity_weight_bounds {
        real_ge(proximity_weight(), real_zero()) && real_le(proximity_weight(), real_one())
    }

    axiom max_raw_score_positive {
        real_gt(max_raw_score(), real_zero())
    }

    axiom weight_sum {
        real_eq(real_add(real_add(base_score_weight(), overlap_weight()), jaccard_weight()), real_one())
    }
}

domain SeqOps {
    function seq_min_int(s: Seq[Int]): Int
    function seq_max_int(s: Seq[Int]): Int
    function seq_sum_int(s: Seq[Int]): Int
    function seq_min_real(s: Seq[Real]): Real
    function seq_max_real(s: Seq[Real]): Real
    function seq_sum_real(s: Seq[Real]): Real
    function seq_contains_int(s: Seq[Int], v: Int): Bool
    function seq_count_distinct(s: Seq[Int]): Int
    function seq_slice(s: Seq[Int], start: Int, end: Int): Seq[Int]

    axiom min_in_seq {
        forall s: Seq[Int] ::
            |s| > 0 ==> seq_contains_int(s, seq_min_int(s))
    }

    axiom max_in_seq {
        forall s: Seq[Int] ::
            |s| > 0 ==> seq_contains_int(s, seq_max_int(s))
    }

    axiom min_le_max {
        forall s: Seq[Int] ::
            |s| > 0 ==> seq_min_int(s) <= seq_max_int(s)
    }

    axiom count_distinct_bounds {
        forall s: Seq[Int] ::
            seq_count_distinct(s) >= 0 && seq_count_distinct(s) <= |s|
    }

    axiom empty_sum {
        seq_sum_int(Seq) == 0
    }

    axiom slice_length {
        forall s: Seq[Int], start: Int, end: Int ::
            (0 <= start && start <= end && end <= |s|) ==>
                |seq_slice(s, start, end)| == end - start
    }

    axiom contains_def {
        forall s: Seq[Int], v: Int ::
            seq_contains_int(s, v) <==> (exists i: Int :: 0 <= i && i < |s| && s[i] == v)
    }
}

field ngram_weights: Seq[Real]
field lsh_hash_params: Seq[Int]
field num_hash_functions: Int
field num_ngrams: Int
field seed: Int
field ranker_valid: Bool

field bitset_bits: Seq[Int]
field bitset_capacity: Int

field tensor_data: Seq[Real]
field tensor_shape: Seq[Int]
field tensor_valid: Bool

field ssi_segments: Map[Int, Ref]
field ssi_valid: Bool

field segment_tokens: Seq[Int]
field segment_score: Real
field segment_position: Int
field segment_anchor: Bool
field segment_anchor_hash: Int
field segment_valid: Bool

field hashmap_keys: Seq[Int]
field hashmap_values: Seq[Int]
field hashmap_count: Int

predicate Ranker(r: Ref) {
    acc(r.ngram_weights) &&
    acc(r.lsh_hash_params) &&
    acc(r.num_hash_functions) &&
    acc(r.num_ngrams) &&
    acc(r.seed) &&
    acc(r.ranker_valid) &&
    r.ranker_valid &&
    r.num_ngrams > 0 &&
    r.num_hash_functions > 0 &&
    |r.ngram_weights| == r.num_ngrams &&
    |r.lsh_hash_params| == r.num_hash_functions * 2 &&
    (forall i: Int :: 0 <= i && i < |r.ngram_weights| ==>
        real_ge(r.ngram_weights[i], real_zero()) &&
        real_le(r.ngram_weights[i], real_one()))
}

predicate RankerReadOnly(r: Ref) {
    acc(r.ngram_weights, 1/2) &&
    acc(r.lsh_hash_params, 1/2) &&
    acc(r.num_hash_functions, 1/2) &&
    acc(r.num_ngrams, 1/2) &&
    acc(r.seed, 1/2) &&
    acc(r.ranker_valid, 1/2) &&
    r.ranker_valid &&
    r.num_ngrams > 0 &&
    r.num_hash_functions > 0 &&
    |r.ngram_weights| == r.num_ngrams &&
    |r.lsh_hash_params| == r.num_hash_functions * 2
}

predicate BitSet(b: Ref) {
    acc(b.bitset_bits) &&
    acc(b.bitset_capacity) &&
    b.bitset_capacity > 0 &&
    |b.bitset_bits| == (b.bitset_capacity + 63) / 64
}

predicate BitSetReadOnly(b: Ref) {
    acc(b.bitset_bits, 1/2) &&
    acc(b.bitset_capacity, 1/2) &&
    b.bitset_capacity > 0 &&
    |b.bitset_bits| == (b.bitset_capacity + 63) / 64
}

predicate Tensor(t: Ref) {
    acc(t.tensor_data) &&
    acc(t.tensor_shape) &&
    acc(t.tensor_valid) &&
    t.tensor_valid &&
    |t.tensor_shape| > 0 &&
    |t.tensor_data| > 0
}

predicate TensorReadOnly(t: Ref) {
    acc(t.tensor_data, 1/2) &&
    acc(t.tensor_shape, 1/2) &&
    acc(t.tensor_valid, 1/2) &&
    t.tensor_valid &&
    |t.tensor_shape| > 0 &&
    |t.tensor_data| > 0
}

predicate RankedSegment(s: Ref) {
    acc(s.segment_tokens) &&
    acc(s.segment_score) &&
    acc(s.segment_position) &&
    acc(s.segment_anchor) &&
    acc(s.segment_anchor_hash) &&
    acc(s.segment_valid) &&
    s.segment_valid &&
    s.segment_position >= 0 &&
    real_ge(s.segment_score, real_zero()) &&
    real_le(s.segment_score, real_one())
}

predicate RankedSegmentReadOnly(s: Ref) {
    acc(s.segment_tokens, 1/2) &&
    acc(s.segment_score, 1/2) &&
    acc(s.segment_position, 1/2) &&
    acc(s.segment_anchor, 1/2) &&
    acc(s.segment_anchor_hash, 1/2) &&
    acc(s.segment_valid, 1/2) &&
    s.segment_valid
}

predicate SSI(ssi: Ref) {
    acc(ssi.ssi_segments) &&
    acc(ssi.ssi_valid) &&
    ssi.ssi_valid
}

predicate SSIReadOnly(ssi: Ref) {
    acc(ssi.ssi_segments, 1/2) &&
    acc(ssi.ssi_valid, 1/2) &&
    ssi.ssi_valid
}

predicate HashMap(m: Ref) {
    acc(m.hashmap_keys) &&
    acc(m.hashmap_values) &&
    acc(m.hashmap_count) &&
    m.hashmap_count >= 0 &&
    |m.hashmap_keys| == |m.hashmap_values| &&
    m.hashmap_count <= |m.hashmap_keys|
}

function tensor_size(shape: Seq[Int]): Int
    requires |shape| > 0
    requires forall i: Int :: 0 <= i && i < |shape| ==> shape[i] > 0
    ensures result > 0
{
    |shape| == 1 ? shape[0] : shape[0] * tensor_size(shape[1..])
}

function min_int(a: Int, b: Int): Int
    ensures result <= a && result <= b
    ensures result == a || result == b
{
    a < b ? a : b
}

function max_int(a: Int, b: Int): Int
    ensures result >= a && result >= b
    ensures result == a || result == b
{
    a > b ? a : b
}

function abs_diff(a: Int, b: Int): Int
    ensures result >= 0
    ensures result == a - b || result == b - a
{
    a > b ? a - b : b - a
}

function compute_weight_decay(index: Int): Real
    requires index >= 0
    ensures real_gt(result, real_zero())
    ensures real_le(result, real_one())
{
    real_div(real_one(), real_from_int(index + 1))
}

function ssi_get_segment(ssi: Ref, hash: Int): Ref
    requires acc(ssi.ssi_segments, 1/4)

function ssi_has_segment(ssi: Ref, hash: Int): Bool
    requires acc(ssi.ssi_segments, 1/4)

method ranker_init(num_ngrams: Int, num_hash_funcs: Int, seed_val: Int) returns (r: Ref)
    requires num_ngrams > 0
    requires num_hash_funcs > 0
    requires seed_val >= 0
    ensures Ranker(r)
    ensures unfolding Ranker(r) in r.num_ngrams == num_ngrams
    ensures unfolding Ranker(r) in r.num_hash_functions == num_hash_funcs
    ensures unfolding Ranker(r) in r.seed == seed_val
    ensures unfolding Ranker(r) in |r.ngram_weights| == num_ngrams
    ensures unfolding Ranker(r) in |r.lsh_hash_params| == num_hash_funcs * 2
{
    r := new(ngram_weights, lsh_hash_params, num_hash_functions, num_ngrams, seed, ranker_valid)
    r.num_ngrams := num_ngrams
    r.num_hash_functions := num_hash_funcs
    r.seed := seed_val
    r.ranker_valid := true
    var weights: Seq[Real] := Seq
    var i: Int := 0
    while (i < num_ngrams)
        invariant 0 <= i && i <= num_ngrams
        invariant |weights| == i
        invariant forall j: Int :: 0 <= j && j < i ==> 
            real_gt(weights[j], real_zero()) && real_le(weights[j], real_one())
        invariant acc(r.ngram_weights)
        invariant acc(r.lsh_hash_params)
        invariant acc(r.num_hash_functions)
        invariant acc(r.num_ngrams)
        invariant acc(r.seed)
        invariant acc(r.ranker_valid)
    {
        weights := weights ++ Seq(compute_weight_decay(i))
        i := i + 1
    }
    r.ngram_weights := weights
    var hash_params: Seq[Int] := Seq
    i := 0
    while (i < num_hash_funcs)
        invariant 0 <= i && i <= num_hash_funcs
        invariant |hash_params| == i * 2
        invariant acc(r.ngram_weights)
        invariant acc(r.lsh_hash_params)
        invariant acc(r.num_hash_functions)
        invariant acc(r.num_ngrams)
        invariant acc(r.seed)
        invariant acc(r.ranker_valid)
    {
        var param_a: Int := hash_wrapping_add(seed_val, hash_wrapping_mul(i, hash_seed_multiplier_a()))
        var param_b: Int := hash_wrapping_add(seed_val, hash_wrapping_mul(i + 1, hash_seed_multiplier_b()))
        hash_params := hash_params ++ Seq(param_a) ++ Seq(param_b)
        i := i + 1
    }
    r.lsh_hash_params := hash_params
    fold Ranker(r)
}

method ranker_deinit(r: Ref)
    requires Ranker(r)
    ensures acc(r.ngram_weights) && acc(r.lsh_hash_params) && acc(r.num_hash_functions) && acc(r.num_ngrams) && acc(r.seed) && acc(r.ranker_valid)
    ensures !r.ranker_valid
{
    unfold Ranker(r)
    r.ngram_weights := Seq
    r.lsh_hash_params := Seq
    r.ranker_valid := false
}

method score_sequence(r: Ref, tokens: Seq[Int], ssi: Ref) returns (score: Real)
    requires RankerReadOnly(r)
    requires SSIReadOnly(ssi)
    requires forall i: Int :: 0 <= i && i < |tokens| ==> tokens[i] >= 0
    ensures RankerReadOnly(r)
    ensures SSIReadOnly(ssi)
    ensures real_ge(score, real_zero())
    ensures real_le(score, real_one())
{
    if (|tokens| == 0) {
        score := real_zero()
    } else {
        unfold RankerReadOnly(r)
        unfold SSIReadOnly(ssi)
        var ngram_score: Real := real_zero()
        var gram: Int := 1
        while (gram < min_int(r.num_ngrams, |tokens| + 1))
            invariant 1 <= gram && gram <= min_int(r.num_ngrams, |tokens| + 1)
            invariant real_ge(ngram_score, real_zero())
            invariant acc(r.ngram_weights, 1/4)
            invariant acc(r.lsh_hash_params, 1/4)
            invariant acc(r.num_hash_functions, 1/4)
            invariant acc(r.num_ngrams, 1/4)
            invariant acc(r.seed, 1/4)
            invariant acc(r.ranker_valid, 1/4)
            invariant acc(ssi.ssi_segments, 1/4)
            invariant acc(ssi.ssi_valid, 1/4)
        {
            if (|tokens| >= gram) {
                var start: Int := 0
                while (start < |tokens| - gram + 1)
                    invariant 0 <= start && start <= |tokens| - gram + 1
                    invariant real_ge(ngram_score, real_zero())
                    invariant acc(r.ngram_weights, 1/8)
                    invariant acc(r.lsh_hash_params, 1/8)
                    invariant acc(r.num_hash_functions, 1/8)
                    invariant acc(r.num_ngrams, 1/8)
                    invariant acc(r.seed, 1/8)
                    invariant acc(r.ranker_valid, 1/8)
                    invariant acc(ssi.ssi_segments, 1/8)
                    invariant acc(ssi.ssi_valid, 1/8)
                {
                    var ngram_slice: Seq[Int] := tokens[start..start + gram]
                    var h: Int := stable_hash(ngram_slice, r.seed)
                    if (ssi_has_segment(ssi, h)) {
                        var seg: Ref := ssi_get_segment(ssi, h)
                        var weight_idx: Int := min_int(gram - 1, |r.ngram_weights| - 1)
                        assume acc(seg.segment_score, 1/16)
                        var seg_score: Real := seg.segment_score
                        ngram_score := real_add(ngram_score, real_mul(r.ngram_weights[weight_idx], seg_score))
                    }
                    start := start + 1
                }
            }
            gram := gram + 1
        }
        var diversity_score: Real := compute_token_diversity_pure(tokens)
        var proximity: Real := compute_anchor_proximity_pure(tokens, ssi)
        var raw_score: Real := real_add(ngram_score, real_add(real_mul(diversity_weight(), diversity_score), real_mul(proximity_weight(), proximity)))
        raw_score := real_clamp(raw_score, real_zero(), max_raw_score())
        score := real_div(raw_score, max_raw_score())
        fold RankerReadOnly(r)
        fold SSIReadOnly(ssi)
    }
}

function compute_token_diversity_pure(tokens: Seq[Int]): Real
    ensures real_ge(result, real_zero())
    ensures real_le(result, real_one())
{
    |tokens| == 0 ? real_zero() : real_div(real_from_int(seq_count_distinct(tokens)), real_from_int(|tokens|))
}

function compute_anchor_proximity_pure(tokens: Seq[Int], ssi: Ref): Real
    requires acc(ssi.ssi_segments, 1/16)
    requires acc(ssi.ssi_valid, 1/16)
    ensures real_ge(result, real_zero())
    ensures real_le(result, real_one())

method compute_token_diversity(r: Ref, tokens: Seq[Int]) returns (diversity: Real)
    requires RankerReadOnly(r)
    ensures RankerReadOnly(r)
    ensures real_ge(diversity, real_zero())
    ensures real_le(diversity, real_one())
{
    if (|tokens| == 0) {
        diversity := real_zero()
    } else {
        var seen: Set[Int] := Set
        var i: Int := 0
        while (i < |tokens|)
            invariant 0 <= i && i <= |tokens|
            invariant |seen| <= i
            invariant RankerReadOnly(r)
        {
            seen := seen union Set(tokens[i])
            i := i + 1
        }
        var unique_count: Int := |seen|
        diversity := real_div(real_from_int(unique_count), real_from_int(|tokens|))
    }
}

method compute_token_overlap(tokens: Seq[Int], query: Seq[Int]) returns (overlap: Real)
    ensures real_ge(overlap, real_zero())
    ensures real_le(overlap, real_one())
{
    if (|tokens| == 0 || |query| == 0) {
        overlap := real_zero()
    } else {
        var overlap_count: Int := 0
        var i: Int := 0
        while (i < |tokens|)
            invariant 0 <= i && i <= |tokens|
            invariant overlap_count >= 0
            invariant overlap_count <= i
        {
            var j: Int := 0
            var found: Bool := false
            while (j < |query| && !found)
                invariant 0 <= j && j <= |query|
            {
                if (tokens[i] == query[j]) {
                    found := true
                }
                j := j + 1
            }
            if (found) {
                overlap_count := overlap_count + 1
            }
            i := i + 1
        }
        var max_len: Int := max_int(|tokens|, |query|)
        overlap := real_div(real_from_int(overlap_count), real_from_int(max_len))
    }
}

method compute_jaccard_similarity(r: Ref, tokens: Seq[Int], query: Seq[Int]) returns (jaccard: Real)
    requires RankerReadOnly(r)
    ensures RankerReadOnly(r)
    ensures real_ge(jaccard, real_zero())
    ensures real_le(jaccard, real_one())
{
    if (|tokens| == 0 && |query| == 0) {
        jaccard := real_one()
    } elseif (|tokens| == 0 || |query| == 0) {
        jaccard := real_zero()
    } else {
        var token_set: Set[Int] := Set
        var i: Int := 0
        while (i < |tokens|)
            invariant 0 <= i && i <= |tokens|
            invariant RankerReadOnly(r)
        {
            token_set := token_set union Set(tokens[i])
            i := i + 1
        }
        var query_set: Set[Int] := Set
        i := 0
        while (i < |query|)
            invariant 0 <= i && i <= |query|
            invariant RankerReadOnly(r)
        {
            query_set := query_set union Set(query[i])
            i := i + 1
        }
        var intersection: Set[Int] := token_set intersection query_set
        var union_set: Set[Int] := token_set union query_set
        var intersection_size: Int := |intersection|
        var union_size: Int := |union_set|
        if (union_size == 0) {
            jaccard := real_zero()
        } else {
            jaccard := real_div(real_from_int(intersection_size), real_from_int(union_size))
        }
    }
}

method anchor_proximity(r: Ref, tokens: Seq[Int], ssi: Ref) returns (proximity: Real)
    requires RankerReadOnly(r)
    requires SSIReadOnly(ssi)
    ensures RankerReadOnly(r)
    ensures SSIReadOnly(ssi)
    ensures real_ge(proximity, real_zero())
    ensures real_le(proximity, real_one())
{
    if (|tokens| == 0) {
        proximity := real_zero()
    } else {
        unfold RankerReadOnly(r)
        unfold SSIReadOnly(ssi)
        var anchors: Int := 0
        var total_dist: Real := real_zero()
        var i: Int := 0
        while (i < |tokens|)
            invariant 0 <= i && i <= |tokens|
            invariant anchors >= 0
            invariant anchors <= i
            invariant real_ge(total_dist, real_zero())
            invariant acc(r.ngram_weights, 1/4)
            invariant acc(r.lsh_hash_params, 1/4)
            invariant acc(r.num_hash_functions, 1/4)
            invariant acc(r.num_ngrams, 1/4)
            invariant acc(r.seed, 1/4)
            invariant acc(r.ranker_valid, 1/4)
            invariant acc(ssi.ssi_segments, 1/4)
            invariant acc(ssi.ssi_valid, 1/4)
        {
            var pos: Int := i
            if (ssi_has_segment(ssi, pos)) {
                var seg: Ref := ssi_get_segment(ssi, pos)
                assume acc(seg.segment_anchor_hash, 1/16)
                assume acc(seg.segment_position, 1/16)
                if (seg.segment_anchor_hash != 0) {
                    anchors := anchors + 1
                    var raw_dist: Int := abs_diff(i, seg.segment_position)
                    var dist: Real := real_from_int(raw_dist)
                    total_dist := real_add(total_dist, dist)
                }
            }
            i := i + 1
        }
        if (anchors == 0) {
            proximity := real_zero()
        } else {
            var denominator: Int := anchors * |tokens|
            var denom_real: Real := real_from_int(max_int(denominator, 1))
            var ratio: Real := real_div(total_dist, denom_real)
            var clamped: Real := real_clamp(ratio, real_zero(), real_one())
            proximity := real_sub(real_one(), clamped)
        }
        fold RankerReadOnly(r)
        fold SSIReadOnly(ssi)
    }
}

method score_sequence_with_query(r: Ref, tokens: Seq[Int], query: Seq[Int], ssi: Ref) returns (score: Real)
    requires RankerReadOnly(r)
    requires SSIReadOnly(ssi)
    ensures RankerReadOnly(r)
    ensures SSIReadOnly(ssi)
    ensures real_ge(score, real_zero())
    ensures real_le(score, real_one())
{
    var base_score: Real
    base_score := score_sequence(r, tokens, ssi)
    var token_overlap: Real
    token_overlap := compute_token_overlap(tokens, query)
    var jaccard: Real
    jaccard := compute_jaccard_similarity(r, tokens, query)
    var combined: Real := real_add(
        real_mul(base_score, base_score_weight()),
        real_add(
            real_mul(token_overlap, overlap_weight()),
            real_mul(jaccard, jaccard_weight())
        )
    )
    score := real_clamp(combined, real_zero(), real_one())
}

method rank_candidates(r: Ref, candidates: Seq[Ref], ssi: Ref) returns (sorted: Seq[Ref])
    requires RankerReadOnly(r)
    requires SSIReadOnly(ssi)
    requires forall i: Int :: 0 <= i && i < |candidates| ==> RankedSegment(candidates[i])
    ensures RankerReadOnly(r)
    ensures SSIReadOnly(ssi)
    ensures |sorted| == |candidates|
    ensures forall i: Int :: 0 <= i && i < |sorted| ==> RankedSegment(sorted[i])
    ensures forall i: Int, j: Int :: 0 <= i && i < j && j < |sorted| ==>
        unfolding RankedSegment(sorted[i]) in
        unfolding RankedSegment(sorted[j]) in
        real_ge(sorted[i].segment_score, sorted[j].segment_score)
{
    if (|candidates| == 0) {
        sorted := Seq
    } else {
        var scores: Seq[Real] := Seq
        var i: Int := 0
        while (i < |candidates|)
            invariant 0 <= i && i <= |candidates|
            invariant |scores| == i
            invariant RankerReadOnly(r)
            invariant SSIReadOnly(ssi)
            invariant forall j: Int :: 0 <= j && j < |candidates| ==> RankedSegment(candidates[j])
        {
            unfold RankedSegment(candidates[i])
            var tokens_i: Seq[Int] := candidates[i].segment_tokens
            fold RankedSegment(candidates[i])
            var score_i: Real
            score_i := score_sequence(r, tokens_i, ssi)
            scores := scores ++ Seq(score_i)
            i := i + 1
        }
        var normalized: Seq[Real]
        normalized := normalize_scores_pure(scores)
        var indices: Seq[Int] := Seq
        i := 0
        while (i < |candidates|)
            invariant 0 <= i && i <= |candidates|
            invariant |indices| == i
        {
            indices := indices ++ Seq(i)
            i := i + 1
        }
        indices := sort_indices_by_scores_desc(indices, normalized)
        sorted := Seq
        i := 0
        while (i < |indices|)
            invariant 0 <= i && i <= |indices|
            invariant |sorted| == i
            invariant forall j: Int :: 0 <= j && j < i ==> RankedSegment(sorted[j])
            invariant forall j: Int :: 0 <= j && j < |candidates| ==> RankedSegment(candidates[j])
        {
            var idx: Int := indices[i]
            sorted := sorted ++ Seq(candidates[idx])
            i := i + 1
        }
    }
}

function sort_indices_by_scores_desc(indices: Seq[Int], scores: Seq[Real]): Seq[Int]
    requires |indices| <= |scores|
    ensures |result| == |indices|
    ensures forall i: Int :: 0 <= i && i < |result| ==> 
        exists j: Int :: 0 <= j && j < |indices| && result[i] == indices[j]
    ensures forall i: Int, j: Int :: 0 <= i && i < j && j < |result| ==>
        real_ge(scores[result[i]], scores[result[j]])

function normalize_scores_pure(scores: Seq[Real]): Seq[Real]
    ensures |result| == |scores|
    ensures forall i: Int :: 0 <= i && i < |result| ==>
        real_ge(result[i], real_zero()) && real_le(result[i], real_one())

method normalize_scores(scores: Seq[Real]) returns (normalized: Seq[Real])
    ensures |normalized| == |scores|
    ensures forall i: Int :: 0 <= i && i < |normalized| ==>
        real_ge(normalized[i], real_zero()) && real_le(normalized[i], real_one())
{
    if (|scores| == 0) {
        normalized := Seq
    } else {
        var min_score: Real := real_inf()
        var max_score: Real := real_neg_inf()
        var valid_count: Int := 0
        var i: Int := 0
        while (i < |scores|)
            invariant 0 <= i && i <= |scores|
            invariant valid_count >= 0
            invariant valid_count <= i
        {
            var s: Real := scores[i]
            if (!real_is_nan(s) && !real_is_inf(s)) {
                valid_count := valid_count + 1
                if (real_lt(s, min_score)) {
                    min_score := s
                }
                if (real_gt(s, max_score)) {
                    max_score := s
                }
            }
            i := i + 1
        }
        if (valid_count == 0) {
            normalized := scores
        } elseif (real_eq(max_score, min_score)) {
            normalized := Seq
            i := 0
            while (i < |scores|)
                invariant 0 <= i && i <= |scores|
                invariant |normalized| == i
                invariant forall j: Int :: 0 <= j && j < i ==>
                    real_ge(normalized[j], real_zero()) && real_le(normalized[j], real_one())
            {
                if (!real_is_nan(scores[i]) && !real_is_inf(scores[i])) {
                    normalized := normalized ++ Seq(real_half())
                } else {
                    normalized := normalized ++ Seq(scores[i])
                }
                i := i + 1
            }
        } else {
            var range: Real := real_sub(max_score, min_score)
            normalized := Seq
            i := 0
            while (i < |scores|)
                invariant 0 <= i && i <= |scores|
                invariant |normalized| == i
                invariant forall j: Int :: 0 <= j && j < i ==>
                    real_ge(normalized[j], real_zero()) && real_le(normalized[j], real_one())
            {
                if (!real_is_nan(scores[i]) && !real_is_inf(scores[i])) {
                    var norm_val: Real := real_div(real_sub(scores[i], min_score), range)
                    normalized := normalized ++ Seq(norm_val)
                } else {
                    normalized := normalized ++ Seq(scores[i])
                }
                i := i + 1
            }
        }
    }
}

method batch_score(r: Ref, sequences: Seq[Seq[Int]], ssi: Ref) returns (scores: Seq[Real])
    requires RankerReadOnly(r)
    requires SSIReadOnly(ssi)
    ensures RankerReadOnly(r)
    ensures SSIReadOnly(ssi)
    ensures |scores| == |sequences|
    ensures forall i: Int :: 0 <= i && i < |scores| ==>
        real_ge(scores[i], real_zero()) && real_le(scores[i], real_one())
{
    if (|sequences| == 0) {
        scores := Seq
    } else {
        scores := Seq
        var b: Int := 0
        while (b < |sequences|)
            invariant 0 <= b && b <= |sequences|
            invariant |scores| == b
            invariant RankerReadOnly(r)
            invariant SSIReadOnly(ssi)
            invariant forall i: Int :: 0 <= i && i < b ==>
                real_ge(scores[i], real_zero()) && real_le(scores[i], real_one())
        {
            var score_b: Real
            score_b := score_sequence(r, sequences[b], ssi)
            scores := scores ++ Seq(score_b)
            b := b + 1
        }
    }
}

method update_weights(r: Ref, gradients: Seq[Real])
    requires Ranker(r)
    ensures Ranker(r)
{
    unfold Ranker(r)
    var i: Int := 0
    var new_weights: Seq[Real] := r.ngram_weights
    while (i < min_int(|r.ngram_weights|, |gradients|))
        invariant 0 <= i && i <= min_int(|r.ngram_weights|, |gradients|)
        invariant |new_weights| == |r.ngram_weights|
        invariant acc(r.ngram_weights)
        invariant acc(r.lsh_hash_params)
        invariant acc(r.num_hash_functions)
        invariant acc(r.num_ngrams)
        invariant acc(r.seed)
        invariant acc(r.ranker_valid)
        invariant forall j: Int :: 0 <= j && j < |new_weights| ==>
            real_ge(new_weights[j], real_zero()) && real_le(new_weights[j], real_one())
    {
        var grad: Real := gradients[i]
        if (!real_is_nan(grad) && !real_is_inf(grad)) {
            var updated: Real := real_add(new_weights[i], real_mul(grad, learning_rate()))
            var clamped: Real := real_clamp(updated, real_zero(), real_one())
            new_weights := new_weights[..i] ++ Seq(clamped) ++ new_weights[i+1..]
        }
        i := i + 1
    }
    r.ngram_weights := new_weights
    fold Ranker(r)
}

method min_hash_signature(r: Ref, tokens: Seq[Int]) returns (sig: Seq[Int])
    requires RankerReadOnly(r)
    ensures RankerReadOnly(r)
    ensures unfolding RankerReadOnly(r) in |sig| == r.num_hash_functions
{
    unfold RankerReadOnly(r)
    var num_funcs: Int := r.num_hash_functions
    var params: Seq[Int] := r.lsh_hash_params
    fold RankerReadOnly(r)
    if (|tokens| == 0) {
        sig := Seq
        var h: Int := 0
        while (h < num_funcs)
            invariant 0 <= h && h <= num_funcs
            invariant |sig| == h
            invariant RankerReadOnly(r)
        {
            sig := sig ++ Seq(2147483647)
            h := h + 1
        }
    } else {
        sig := Seq
        var h: Int := 0
        while (h < num_funcs)
            invariant 0 <= h && h <= num_funcs
            invariant |sig| == h
            invariant RankerReadOnly(r)
        {
            var min_hash: Int := 2147483647
            var seed_a: Int := params[h * 2]
            var seed_b: Int := params[h * 2 + 1]
            var t: Int := 0
            while (t < |tokens|)
                invariant 0 <= t && t <= |tokens|
                invariant min_hash >= 0
            {
                var hash_val: Int := hash_xor(stable_hash_single(tokens[t], seed_a), seed_b)
                if (hash_val >= 0 && hash_val < min_hash) {
                    min_hash := hash_val
                }
                t := t + 1
            }
            sig := sig ++ Seq(min_hash)
            h := h + 1
        }
    }
}

method jaccard_similarity_from_signatures(sig1: Seq[Int], sig2: Seq[Int]) returns (sim: Real)
    ensures real_ge(sim, real_zero())
    ensures real_le(sim, real_one())
{
    if (|sig1| != |sig2|) {
        sim := real_zero()
    } elseif (|sig1| == 0) {
        sim := real_zero()
    } else {
        var matches: Int := 0
        var i: Int := 0
        while (i < |sig1|)
            invariant 0 <= i && i <= |sig1|
            invariant matches >= 0
            invariant matches <= i
        {
            if (sig1[i] == sig2[i]) {
                matches := matches + 1
            }
            i := i + 1
        }
        sim := real_div(real_from_int(matches), real_from_int(|sig1|))
    }
}

method estimate_jaccard(set1: Ref, set2: Ref) returns (est: Real)
    requires BitSetReadOnly(set1)
    requires BitSetReadOnly(set2)
    ensures BitSetReadOnly(set1)
    ensures BitSetReadOnly(set2)
    ensures real_ge(est, real_zero())
    ensures real_le(est, real_one())
{
    unfold BitSetReadOnly(set1)
    unfold BitSetReadOnly(set2)
    var intersect: Int := 0
    var union_count: Int := 0
    var words: Int := min_int(|set1.bitset_bits|, |set2.bitset_bits|)
    var i: Int := 0
    while (i < words)
        invariant 0 <= i && i <= words
        invariant intersect >= 0
        invariant union_count >= 0
        invariant intersect <= union_count
        invariant acc(set1.bitset_bits, 1/4)
        invariant acc(set1.bitset_capacity, 1/4)
        invariant acc(set2.bitset_bits, 1/4)
        invariant acc(set2.bitset_capacity, 1/4)
    {
        intersect := intersect + pop_count(bit_and(set1.bitset_bits[i], set2.bitset_bits[i]))
        union_count := union_count + pop_count(bit_or(set1.bitset_bits[i], set2.bitset_bits[i]))
        i := i + 1
    }
    fold BitSetReadOnly(set1)
    fold BitSetReadOnly(set2)
    if (union_count == 0) {
        est := real_zero()
    } else {
        est := real_div(real_from_int(intersect), real_from_int(union_count))
    }
}

method vector_score(embedding: Ref, query_emb: Ref) returns (score: Real)
    requires TensorReadOnly(embedding)
    requires TensorReadOnly(query_emb)
    ensures TensorReadOnly(embedding)
    ensures TensorReadOnly(query_emb)
    ensures real_ge(score, real_neg_one())
    ensures real_le(score, real_one())
{
    unfold TensorReadOnly(embedding)
    unfold TensorReadOnly(query_emb)
    if (embedding.tensor_shape != query_emb.tensor_shape) {
        fold TensorReadOnly(embedding)
        fold TensorReadOnly(query_emb)
        assume false
        score := real_zero()
    } elseif (|embedding.tensor_data| == 0) {
        fold TensorReadOnly(embedding)
        fold TensorReadOnly(query_emb)
        score := real_zero()
    } else {
        var dot_prod: Real := real_zero()
        var norm_emb: Real := real_zero()
        var norm_query: Real := real_zero()
        var len: Int := |embedding.tensor_data|
        var i: Int := 0
        while (i < len)
            invariant 0 <= i && i <= len
            invariant real_ge(norm_emb, real_zero())
            invariant real_ge(norm_query, real_zero())
            invariant acc(embedding.tensor_data, 1/4)
            invariant acc(embedding.tensor_shape, 1/4)
            invariant acc(embedding.tensor_valid, 1/4)
            invariant acc(query_emb.tensor_data, 1/4)
            invariant acc(query_emb.tensor_shape, 1/4)
            invariant acc(query_emb.tensor_valid, 1/4)
        {
            var e: Real := embedding.tensor_data[i]
            var q: Real := query_emb.tensor_data[i]
            if (!real_is_nan(e) && !real_is_nan(q) && !real_is_inf(e) && !real_is_inf(q)) {
                dot_prod := real_add(dot_prod, real_mul(e, q))
                norm_emb := real_add(norm_emb, real_mul(e, e))
                norm_query := real_add(norm_query, real_mul(q, q))
            }
            i := i + 1
        }
        fold TensorReadOnly(embedding)
        fold TensorReadOnly(query_emb)
        if (real_le(norm_emb, real_zero()) || real_le(norm_query, real_zero())) {
            score := real_zero()
        } else {
            norm_emb := real_sqrt(norm_emb)
            norm_query := real_sqrt(norm_query)
            if (real_eq(norm_emb, real_zero()) || real_eq(norm_query, real_zero())) {
                score := real_zero()
            } else {
                var result: Real := real_div(dot_prod, real_mul(norm_emb, norm_query))
                score := real_clamp(result, real_neg_one(), real_one())
            }
        }
    }
}

