method topKHeap(r: Ref, ssi: Ref, query: Seq[Int], k: Int, allocator: Ref) returns (result: Seq[Ref])
    requires Ranker(r) && acc(query)
    requires k >= 0
    ensures forall c: Ref :: 0 <= c && c < result.length ==> RankedSegment(result[c])
{
    if (k == 0) {
        result := Seq
        return
    }

    var heap := PriorityQueue_init(allocator)
    var candidates := SSI_retrieveTopK(ssi, query, RankerConfig_DEFAULT_TOP_K_RETRIEVAL(), allocator)

    var i: Int := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant PriorityQueue(heap)
        invariant forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
    {
        var cand := candidates[i]
        var score: Real := scoreSequenceWithQuery(r, RankedSegment_tokens(cand), query, ssi)

        if (!Real_isNan(score) && !Real_isInf(score)) {
            if (PriorityQueue_count(heap) < k) {
                var ranked := RankedSegment_init(allocator, RankedSegment_tokens(cand), score, RankedSegment_position(cand), RankedSegment_anchor(cand))
                PriorityQueue_add(heap, ranked)
            } else if (PriorityQueue_peek(heap)) {
                var top := PriorityQueue_peek(heap)
                if (score > RankedSegment_score(top)) {
                    var removed := PriorityQueue_remove(heap)
                    RankedSegment_deinit(removed, allocator)
                    var ranked := RankedSegment_init(allocator, RankedSegment_tokens(cand), score, RankedSegment_position(cand), RankedSegment_anchor(cand))
                    PriorityQueue_add(heap, ranked)
                }
            }
        }
        i := Int_add(i, 1)
    }

    var result_count: Int := PriorityQueue_count(heap)
    result := Seq[Ref](result_count, _ => null)

    var idx: Int := result_count
    while (PriorityQueue_removeOrNull(heap))
        invariant idx >= 0 && idx <= result_count
        invariant PriorityQueue(heap)
    {
        var item := PriorityQueue_removeOrNull(heap)
        if (idx > 0) {
            idx := Int_sub(idx, 1)
            result := result.updated(idx, item)
        } else {
            RankedSegment_deinit(item, allocator)
        }
    }
}

method updateWeights(r: Ref, gradients: Seq[Real])
    requires Ranker(r) && acc(gradients)
    ensures Ranker(r)
{
    var i: Int := 0
    while (i < Int_min(r.ngram_weights.length, gradients.length))
        invariant 0 <= i && i <= Int_min(r.ngram_weights.length, gradients.length)
        invariant forall j: Int :: 0 <= j && j < i ==>
            !Real_isNan(gradients[j]) && !Real_isInf(gradients[j]) ==>
            r.ngram_weights[j] == Real_add(old(r.ngram_weights[j]), Real_mul(gradients[j], RankerConfig_LEARNING_RATE()))
    {
        var grad := gradients[i]
        if (!Real_isNan(grad) && !Real_isInf(grad)) {
            r.ngram_weights := r.ngram_weights.updated(i, Real_add(r.ngram_weights[i], Real_mul(grad, RankerConfig_LEARNING_RATE())))
            r.ngram_weights := r.ngram_weights.updated(i, Real_clamp(r.ngram_weights[i], 0.0, 1.0))
        }
        i := Int_add(i, 1)
    }
}

method minHashSignature(r: Ref, tokens: Seq[Int]) returns (sig: Seq[Int])
    requires Ranker(r) && acc(tokens)
    ensures sig.length == r.num_hash_functions
{
    if (tokens.length == 0) {
        sig := Seq[Int](r.num_hash_functions, _ => Int_max(0, 18446744073709551615))
        return
    }

    sig := Seq[Int](r.num_hash_functions, _ => 0)
    var h: Int := 0
    while (h < r.num_hash_functions)
        invariant 0 <= h && h <= r.num_hash_functions
        invariant sig.length == r.num_hash_functions
        invariant forall j: Int :: 0 <= j && j < h ==> sig[j] == minHashForFunction(r, tokens, j)
    {
        var min_hash: Int := Int_max(0, 18446744073709551615)
        var seed_a: Int := r.lsh_hash_params[Int_mul(h, 2)]
        var seed_b: Int := r.lsh_hash_params[Int_add(Int_mul(h, 2), 1)]

        var i: Int := 0
        while (i < tokens.length)
            invariant 0 <= i && i <= tokens.length
            invariant min_hash <= Int_max(0, 18446744073709551615)
        {
            var hash_val: Int := Int_xor(stableHash(asBytes(tokens[i]), seed_a), seed_b)
            if (hash_val < min_hash) {
                min_hash := hash_val
            }
            i := Int_add(i, 1)
        }
        sig := sig.updated(h, min_hash)
        h := Int_add(h, 1)
    }
}

method jaccardSimilarityFromSignatures(sig1: Seq[Int], sig2: Seq[Int]) returns (result: Real)
    requires acc(sig1) && acc(sig2)
    ensures result >= 0.0 && result <= 1.0
{
    if (sig1.length != sig2.length) {
        result := 0.0
        return
    }
    if (sig1.length == 0) {
        result := 0.0
        return
    }

    var matches: Int := 0
    var i: Int := 0
    while (i < sig1.length)
        invariant 0 <= i && i <= sig1.length
        invariant matches >= 0
    {
        if (sig1[i] == sig2[i]) {
            matches := Int_add(matches, 1)
        }
        i := Int_add(i, 1)
    }
    result := Real_div(Real_fromInt(matches), Real_fromInt(sig1.length))
}

method estimateJaccard(set1: Ref, set2: Ref) returns (result: Real)
    requires BitSet(set1) && BitSet(set2)
    ensures result >= 0.0 && result <= 1.0
{
    var intersect: Int := 0
    var union_count: Int := 0
    var words: Int := Int_min(BitSet_bits(set1).length, BitSet_bits(set2).length)
    var i: Int := 0
    while (i < words)
        invariant 0 <= i && i <= words
        invariant intersect >= 0 && union_count >= 0
    {
        intersect := Int_add(intersect, popCount(Int_and(BitSet_bits(set1)[i], BitSet_bits(set2)[i])))
        union_count := Int_add(union_count, popCount(Int_or(BitSet_bits(set1)[i], BitSet_bits(set2)[i])))
        i := Int_add(i, 1)
    }
    if (union_count == 0) {
        result := 0.0
    } else {
        result := Real_div(Real_fromInt(intersect), Real_fromInt(union_count))
    }
}

method vectorScore(embedding: Ref, query_emb: Ref) returns (result: Real)
    requires Tensor(embedding) && Tensor(query_emb)
    requires memEql(Tensor_shape_dims(embedding), Tensor_shape_dims(query_emb))
    requires Tensor_data(embedding).length > 0
    ensures result >= -1.0 && result <= 1.0
{
    var dot_prod: Real := 0.0
    var norm_emb: Real := 0.0
    var norm_query: Real := 0.0

    var len: Int := Tensor_data(embedding).length
    var i: Int := 0
    while (i < len)
        invariant 0 <= i && i <= len
        invariant dot_prod >= 0.0 || (dot_prod <= 0.0 && Real_abs(dot_prod) <= Real_mul(Real_fromInt(i), 1.0))
        invariant norm_emb >= 0.0
        invariant norm_query >= 0.0
    {
        var e: Real := Tensor_data(embedding)[i]
        var q: Real := Tensor_data(query_emb)[i]

        if (!Real_isNan(e) && !Real_isNan(q) && !Real_isInf(e) && !Real_isInf(q)) {
            dot_prod := Real_add(dot_prod, Real_mul(e, q))
            norm_emb := Real_add(norm_emb, Real_mul(e, e))
            norm_query := Real_add(norm_query, Real_mul(q, q))
        }
        i := Int_add(i, 1)
    }

    if (norm_emb <= 0.0 || norm_query <= 0.0) {
        result := 0.0
        return
    }

    norm_emb := Real_sqrt(norm_emb)
    norm_query := Real_sqrt(norm_query)

    if (norm_emb == 0.0 || norm_query == 0.0) {
        result := 0.0
        return
    }

    result := Real_div(dot_prod, Real_mul(norm_emb, norm_query))
    result := Real_clamp(result, -1.0, 1.0)
}

method dotProductScore(embedding: Ref, query_emb: Ref) returns (result: Real)
    requires Tensor(embedding) && Tensor(query_emb)
    requires memEql(Tensor_shape_dims(embedding), Tensor_shape_dims(query_emb))
    requires Tensor_data(embedding).length > 0
{
    var dot_prod: Real := 0.0
    var len: Int := Tensor_data(embedding).length
    var i: Int := 0
    while (i < len)
        invariant 0 <= i && i <= len
        invariant dot_prod >= 0.0 || (dot_prod <= 0.0 && Real_abs(dot_prod) <= Real_mul(Real_fromInt(i), 1.0))
    {
        var e: Real := Tensor_data(embedding)[i]
        var q: Real := Tensor_data(query_emb)[i]

        if (!Real_isNan(e) && !Real_isNan(q) && !Real_isInf(e) && !Real_isInf(q)) {
            dot_prod := Real_add(dot_prod, Real_mul(e, q))
        }
        i := Int_add(i, 1)
    }
    result := dot_prod
}

method weightedAverage(scores: Seq[Real], weights: Seq[Real]) returns (result: Real)
    requires acc(scores) && acc(weights)
    requires scores.length == weights.length
    requires scores.length > 0
    ensures !Real_isNan(result) && !Real_isInf(result)
{
    var num: Real := 0.0
    var den: Real := 0.0
    var i: Int := 0
    while (i < scores.length)
        invariant 0 <= i && i <= scores.length
        invariant num >= 0.0 || (num <= 0.0 && Real_abs(num) <= Real_mul(Real_fromInt(i), 1.0))
        invariant den >= 0.0
    {
        var s: Real := scores[i]
        var w: Real := weights[i]

        if (!Real_isNan(s) && !Real_isNan(w) && !Real_isInf(s) && !Real_isInf(w)) {
            num := Real_add(num, Real_mul(s, w))
            den := Real_add(den, w)
        }
        i := Int_add(i, 1)
    }

    if (den == 0.0) {
        result := 0.0
    } else {
        result := Real_div(num, den)
    }
}

method exponentialDecay(scores: Seq[Ref], decay_factor: Real)
    requires acc(scores)
    requires decay_factor > 0.0 && decay_factor < 1.0
    ensures acc(scores)
{
    if (scores.length == 0) {
        return
    }

    var current_decay: Real := 1.0
    var i: Int := 0
    while (i < scores.length)
        invariant 0 <= i && i <= scores.length
        invariant current_decay >= 0.0 && current_decay <= 1.0
    {
        if (!Real_isNan(scores[i]) && !Real_isInf(scores[i])) {
            scores[i] := Real_mul(scores[i], current_decay)
        }
        current_decay := Real_mul(current_decay, decay_factor)
        i := Int_add(i, 1)
    }
}

method normalizeScoresStatic(scores: Seq[Ref])
    requires acc(scores)
    ensures acc(scores)
{
    if (scores.length == 0) {
        return
    }

    var min_score: Real := Real_inf()
    var max_score: Real := Real_negInf()
    var valid_count: Int := 0

    var i: Int := 0
    while (i < scores.length)
        invariant 0 <= i && i <= scores.length
        invariant valid_count >= 0
        invariant min_score <= Real_inf() && max_score >= Real_negInf()
    {
        var s: Real := scores[i]
        if (!Real_isNan(s) && !Real_isInf(s)) {
            valid_count := Int_add(valid_count, 1)
            if (s < min_score) {
                min_score := s
            }
            if (s > max_score) {
                max_score := s
            }
        }
        i := Int_add(i, 1)
    }

    if (valid_count == 0) {
        return
    }
    if (max_score == min_score) {
        i := 0
        while (i < scores.length)
            invariant 0 <= i && i <= scores.length
        {
            if (!Real_isNan(scores[i]) && !Real_isInf(scores[i])) {
                scores[i] := 0.5
            }
            i := Int_add(i, 1)
        }
        return
    }

    var range: Real := Real_sub(max_score, min_score)
    i := 0
    while (i < scores.length)
        invariant 0 <= i && i <= scores.length
    {
        if (!Real_isNan(scores[i]) && !Real_isInf(scores[i])) {
            scores[i] := Real_div(Real_sub(scores[i], min_score), range)
        }
        i := Int_add(i, 1)
    }
}

method rankByMultipleCriteria(r: Ref, candidates: Seq[Ref], criteria: Seq[Seq[Real]], weights: Seq[Real], allocator: Ref)
    requires Ranker(r) && acc(candidates) && acc(criteria) && acc(weights)
    requires forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
